          mozilla::components::FolderNotification::Service();
      if (m_copyState) {
        if (imapAction == nsIImapUrl::nsImapOnlineMove) {
          notifier->NotifyMsgsMoveCopyCompleted(true, m_copyState->m_messages,
                                                this, {});
